param([Parameter(Mandatory=$true)][string]$Domain,[string]$EnvironmentFile='.env.staging',[Parameter(Mandatory=$true)][string]$ConfirmRollback)
$ErrorActionPreference='Stop';if($ConfirmRollback-ne'ROLLBACK_WAREVANTA_STAGING'){throw 'Pass -ConfirmRollback ROLLBACK_WAREVANTA_STAGING.'};$project=Split-Path -Parent $PSScriptRoot;$previous=Join-Path $project '.runtime\staging-previous-image';if(-not(Test-Path -LiteralPath $previous)){throw 'No previous staging image has been recorded.'};$image=(Get-Content -LiteralPath $previous -Raw).Trim();if($image-notmatch'@sha256:[a-fA-F0-9]{64}$'){throw 'Recorded rollback image is invalid.'};$env:WAREVANTA_IMAGE=$image;$env:WAREVANTA_DOMAIN=$Domain;& docker compose --env-file (Join-Path $project $EnvironmentFile) -f (Join-Path $project 'compose.staging.yml') up -d --remove-orphans;if($LASTEXITCODE){throw 'Rollback failed'};& (Join-Path $PSScriptRoot 'health-check.ps1') -Url "https://$Domain/api/ready";Set-Content -LiteralPath (Join-Path $project '.runtime\staging-current-image') -Value $image;Write-Output "Staging rolled back to $image"
